<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class PembukuanBaruBukuBesarController extends Controller {
 private function periode(Request $r){return [$r->tgl1?:DB::table('jurnal_perkiraan')->min('tanggal')?:date('Y-m-01'),$r->tgl2?:DB::table('jurnal_perkiraan')->max('tanggal')?:date('Y-m-d')];}
 public function index(Request $r){[$tgl1,$tgl2]=$this->periode($r);$cari=trim((string)$r->cari);$buku=DB::table('akun_perkiraan as a')->leftJoin('jurnal_perkiraan as j',function($q)use($tgl1,$tgl2){$q->on('j.id_akun_perkiraan','=','a.id_akun_perkiraan')->whereBetween('j.tanggal',[$tgl1,$tgl2]);})->when($cari,fn($q)=>$q->where(fn($w)=>$w->where('a.kode_perkiraan','like',"%$cari%")->orWhere('a.nama','like',"%$cari%")))->select('a.id_akun_perkiraan','a.kode_perkiraan','a.nama','a.tipe_akun')->selectRaw('COALESCE(SUM(j.debit),0) debit, COALESCE(SUM(j.kredit),0) kredit, COALESCE(SUM(j.debit-j.kredit),0) saldo')->groupBy('a.id_akun_perkiraan','a.kode_perkiraan','a.nama','a.tipe_akun')->orderBy('a.kode_perkiraan')->paginate(20)->withQueryString();return view('pembukuan_baru.buku_besar.index',compact('buku','tgl1','tgl2')+['title'=>'Buku Besar']);}
 public function detail(Request $r,int $id){[$tgl1,$tgl2]=$this->periode($r);$akun=DB::table('akun_perkiraan')->where('id_akun_perkiraan',$id)->first();abort_if(!$akun,404);$detail=DB::table('jurnal_perkiraan')->where('id_akun_perkiraan',$id)->whereBetween('tanggal',[$tgl1,$tgl2])->when($r->cari,fn($q)=>$q->where(fn($w)=>$w->where('nomor_transaksi','like','%'.$r->cari.'%')->orWhere('deskripsi','like','%'.$r->cari.'%')->orWhere('tipe_transaksi','like','%'.$r->cari.'%')))->orderBy('tanggal')->orderBy('nomor_transaksi')->paginate(20)->withQueryString();$saldo=0;foreach($detail as $d){$saldo+=(float)$d->debit-(float)$d->kredit;$d->saldo=$saldo;}return view('pembukuan_baru.buku_besar.detail',compact('akun','detail','tgl1','tgl2')+['title'=>'Detail Buku Besar']);}
}
